import ua.ember.*;
public final class UpdateTest {
 private static int passed;
 private static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);passed++;System.out.println("PASS "+text);}
 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte n:b)s.append(String.format("%02X",n&255));return s.toString();}
 public static void main(String[] args){check(DeviceProfiles.detect("ELK-BLEDOB","0000fff3")==0,"BLEDOB automatic profile");check(DeviceProfiles.detect("MELK","0000ffe1")==1,"MELK automatic profile");check(DeviceProfiles.detect("ELK-BLEDOM","0000ffe9")==2,"alternate ELK characteristic");check(DeviceProfiles.detect("Triones","0000ffd9")==3,"Triones automatic profile");boolean rejected=false;try{DeviceProfiles.detect("Unknown","0000fff3");}catch(IllegalArgumentException e){rejected=true;}check(rejected,"unknown protocol rejected");DeviceProfiles.Adapter a=new DeviceProfiles.Adapter();a.profile=3;check(hex(a.convert(LedProtocol.color(0xff5a1f))).equals("56FF5A1F00F0AA"),"Triones RGB");check(hex(a.convert(LedProtocol.brightness(50,3))).equals("567F2D0F00F0AA"),"Triones brightness");check(hex(a.convert(LedProtocol.power(false,3))).equals("CC2433"),"Triones power");check(a.convert(LedProtocol.mic(false)).length==0,"no foreign mic command");for(int i=0;i<16;i++){MicPresets.check(i);check((LedProtocol.micMode(MicPresets.MODES[i])[3]&255)==128+MicPresets.MODES[i],"native microphone preset "+i);}EffectEngine.Signal f=new EffectEngine.Signal();f.rms=.2;f.bass=.15;f.peak=.5;for(String id:new String[]{"pulse","bass","jump3","jump7","fade","spectrum","wave","strobe","fire","aurora","breath","echo","spark","ocean","duo","neon"}){ReactiveEngine engine=new ReactiveEngine();int bright=engine.render(id,0xff5a1f,1,f,true),quiet=engine.render(id,0xff5a1f,10,null,false);check((bright&255)+((bright>>8)&255)+((bright>>16)&255)>(quiet&255)+((quiet>>8)&255)+((quiet>>16)&255),"music response "+id);}System.out.println("TOTAL "+passed);}
}
